// Notifications only: no fetch interception or caching of either local game.
self.addEventListener('push',event=>{let data;try{data=event.data.json();}catch{return;}if(!data||typeof data.roomId!=='string'||!/^[A-Z2-9]{8}$/.test(data.roomId))return;const url=new URL('online.html?room='+data.roomId,self.registration.scope);event.waitUntil(self.registration.showNotification(data.title||'피츠버그',{body:data.body||'대국을 확인하세요.',tag:'pittsburgh-'+data.roomId,data:{url:url.href},icon:new URL('og.png',self.registration.scope).href}));});
self.addEventListener('notificationclick',event=>{event.notification.close();const url=new URL(event.notification.data?.url||'online.html',self.registration.scope);if(url.origin!==self.location.origin)return;event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(async list=>{const existing=list.find(client=>client.url===url.href);if(existing)return existing.focus();return clients.openWindow(url.href);}));});
